      // single flat colour (that is exactly the black screen the user saw).
      const shot = await sh(`DISPLAY=${DISPLAY} import -window root -crop 40x40+0+0 txt:- 2>/dev/null | tail -n +2 | awk '{print $3}' | sort -u | wc -l`, 20000);
