    localStatus,
    ensureNow: () => fullStart(repoRootRef),
    repair: (why) => repair(repoRootRef, why || 'manual'),
    tick,
    size: () => desktopSize(),
    registerProxy,
    stop: () => clearInterval(timer),
    keepalive: state
  };
}

